def nacti_vek(text):
    vek = int(text)
    # Vlastní pravidlo také oznámíme výjimkou.
    if vek < 0:
        raise ValueError("Věk nesmí být záporný")
    return vek


for text in ["15", "-2", "x"]:
    try:
        print(nacti_vek(text))
    except ValueError as chyba:
        print("Nelze přijmout:", chyba)
    # finally se provede při úspěchu i chybě.
    finally:
        print("Zpracováno")

for text in ["4", "0", "nic"]:
    try:
        vysledek = 20 / int(text)
    # Každý typ chyby dostane vlastní zprávu.
    except ValueError:
        print("Zadejte celé číslo.")
    except ZeroDivisionError:
        print("Nulou dělit nelze.")
    # else patří jen k úspěšnému výpočtu.
    else:
        print("Výsledek:", vysledek)
